divisionAttach=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(proc.state,"division",division);feelAttach=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(proc.state,"feel",feel);
for(auto* b:{&time,&space,&refine,&bypass,&reset,&ping})addAndMakeVisible(b);for(auto pair:{std::pair{&ping,"pingpong"},std::pair{&time,"timeOn"},std::pair{&space,"spaceOn"},std::pair{&bypass,"bypass"}}){pair.first->setClickingTogglesState(true);buttons.push_back(std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(proc.state,pair.second,*pair.first));}
