SpaceEditor::~SpaceEditor(){stopTimer();setLookAndFeel(nullptr);}
void SpaceEditor::fillPresets(){preset.clear(juce::dontSendNotification);auto cat=category.getText();for(int i=0;i<20;++i)if(cat==presets[i].category)preset.addItem(presets[i].name,i+1);if(cat==presets[proc.getCurrentProgram()].category)preset.setSelectedId(proc.getCurrentProgram()+1,juce::dontSendNotification);else preset.setSelectedItemIndex(0,juce::sendNotificationSync);}
void SpaceEditor::timerCallback(){int program=proc.getCurrentProgram();if(program!=shownProgram){shownProgram=program;for(int i=0;i<category.getNumItems();++i)if(category.getItemText(i)==presets[program].category)category.setSelectedItemIndex(i,juce::dontSendNotification);fillPresets();}time.setButtonText(time.getToggleState()?"Actif":"Coupe");space.setButtonText(space.getToggleState()?"Actif":"Coupe");in=std::max(in*.8f,proc.inputPeak.exchange(0));out=std::max(out*.8f,proc.outputPeak.exchange(0));history[historyPos]=out;historyPos=(historyPos+1)%240;sliders[16].setEnabled(!proc.hostTempo.load());repaint();}
